      const f7 = /\] (GP1-[A-Z0-9-]+) and (GP1-[A-Z0-9-]+) \(helper :\d+ and :\d+\) read the spy and global-stub callee by its spelling only/.exec(bulletOf(block, "F7 INFO"));
