  describe("LOCATIONS (wb-tz2.20 seat sweep): each C2, driver and shape form read where it stands, in a function body, a block, a class static block and a namespace", () => {
    it("the located words are the C2, driver and shape roster words, in order", () => {
      expect(LOCATED.map(row => row.word)).toStrictEqual([...C2_FORMS, ...DRIVER_FORMS, ...SHAPE_FORMS].map(form => form.word));
    });
    it("each located text holds its body in its wrapper: after the head's statements, one statement of the wrapper's kind", () => {
      const holder = (statement: ts.Statement | undefined): string => {
        if (statement === undefined) return "<none>";
        if (ts.isFunctionDeclaration(statement) && statement.body !== undefined) return "function body";
        if (ts.isBlock(statement)) return "block";
        if (ts.isClassDeclaration(statement) && statement.members.some(ts.isClassStaticBlockDeclaration)) return "class static block";
        return ts.isModuleDeclaration(statement) ? "namespace" : ts.SyntaxKind[statement.kind];
      };
      const placed = (row: LocatedRow, location: LocationRow): string => {
        const statements = parseText(PLANT, locatedText(row, location)).statements;
        const head = parseText(PLANT, row.head).statements.length;
        return `${row.word} in a ${location.id}: ${statements.length - head} ${holder(statements[statements.length - 1])}`;
      };
      expect(LOCATED.flatMap(row => LOCATIONS.map(location => placed(row, location)))).toStrictEqual(LOCATED.flatMap(row => LOCATIONS.map(location => `${row.word} in a ${location.id}: 1 ${location.id}`)));
    });
    it.each(LOCATED.flatMap(row => LOCATIONS.map(location => [`${row.word} in a ${location.id}`, row, location] as const)))("%s", (_name, row, location) => {
      expect(subReading({ id: row.word, claim: location.id, kind: row.kind, text: locatedText(row, location), expected: row.expected })).toStrictEqual(row.expected);
    });
  });

