  describe("FOLLOW-UP ANCHOR (wb-zchj, outside this census): the follow-up bead's F1 finding in the tracker export", () => {
    it("every wb-zchj requirement line this census answers occurs verbatim in its notes, and the requirement lines are exactly the F1 finding's defect sentence and its optional cure sentence, in both directions", () => {
      const notes = exportRecord(FOLLOW_UP).notes;
      const finding = followUpFinding();
      const defect = finding.indexOf("No census row plants ");
      const defectEnd = defect < 0 ? -1 : finding.indexOf(". ", defect);
      const cure = finding.indexOf("Optional cure: ");
      expect({
        missing: FOLLOW_UP_REQUIREMENTS.filter(requirement => !notes.includes(requirement.text)).map(requirement => requirement.key),
        lines: FOLLOW_UP_REQUIREMENTS.map(requirement => requirement.text),
      }).toStrictEqual({
        missing: [],
        lines: [...(defectEnd < 0 ? [] : [finding.slice(defect, defectEnd + 1)]), ...(cure < 0 ? [] : [finding.slice(cure)])],
      });
    });
    it("the members the F1 finding names, each with the text it replaces and its replacement as the finding quotes them and in order, are exactly the NARROWING_MEMBERS rows, each with the witness the finding names for it", () => {
      const finding = followUpFinding();
      const witnesses = new Map([...finding.matchAll(/For (CL-[A-Z]+) the witness is (?:the seat battery entry )?([A-Z][A-Z0-9-]*)[,:]/g)].map(match => [match[1] ?? "", match[2] ?? ""] as const));
      const members = [...finding.matchAll(/(CL-[A-Z]+) replaces (.+?) with '(.+?)'\. /g)].map(match => ({ id: match[1] ?? "", replaces: match[2] ?? "", replacement: match[3] ?? "", witness: witnesses.get(match[1] ?? "") ?? "" }));
      expect(members).toStrictEqual(NARROWING_MEMBERS);
    });
    it("each member's witness, as the F1 finding states it, is a NARROWING_CONTROLS row on the helper header's own line it names: P-L016-WIDEN that line with the finding's quoted words added, ENDCLAUSE that line with its clause moved to the line end, ending in the finding's quoted tail", () => {
      const finding = followUpFinding();
      const lines = new Map(helperClaimLines().map(entry => [entry.id, entry.line] as const));
      const held = [...finding.matchAll(/For (CL-[A-Z]+) the witness is (?:the seat battery entry )?([A-Z][A-Z0-9-]*)[,:] (.*?)(?= For CL-| No census row )/g)].map(match => {
        const control = NARROWING_CONTROLS.find(row => row.id === match[2]);
        const description = match[3] ?? "";
        const gains = /(L\d{3}) gains '([^']+)'/.exec(description);
        const moved = /(L\d{3})'s clause moved to the line end \('\.\.\. ([^']+)'\)/.exec(description);
        const id = gains?.[1] ?? moved?.[1] ?? "";
        const narrowed = lines.get(id);
        const added = gains?.[2];
        const tail = moved?.[2];
        const replayed =
          control !== undefined &&
          narrowed !== undefined &&
          control.narrowed === narrowed &&
          (added !== undefined
            ? control.line.includes(added) && control.line.replace(` ${added}`, "") === narrowed
            : tail !== undefined && control.line.endsWith(tail) && control.line.replace(" on its pinned pages.", ".") === narrowed.replace("on its pinned pages, ", ""));
        return `${match[1] ?? ""} ${match[2] ?? ""} on ${id}: ${replayed ? "replayed" : "not replayed"}`;
      });
      expect(held).toStrictEqual(NARROWING_MEMBERS.map(member => `${member.id} ${member.witness} on L016: replayed`));
    });
    it("the control classes the F1 finding's cure names - each named widening word, the phrase outside clause position, an unnarrowed line - are, in order, the items of the NARROWING_CONTROLS rows", () => {
      expect([...new Set(NARROWING_CONTROLS.map(row => row.item))]).toStrictEqual(cureClasses(followUpFinding()));
    });
  });

  describe("PREDICATE WORDS ANCHOR (wb-zchj, outside this census): the widening words and the places narrowsToPinnedPages names, as the tracker export states them", () => {
    it("the widening words the carrier's cut #1 delivery note names for refusal #4 F2, then the one its cut #5 delivery note adds, are, in order, the words of the widening rows, the witness aside; each row's line spells its word and no other, and its narrowed line none", () => {
      const [widening = ""] = cureClasses(followUpFinding());
      const words = predicateWideningWords();
      const witnesses = NARROWING_MEMBERS.map(member => member.witness);
      const rows = NARROWING_CONTROLS.filter(row => row.item === widening && !witnesses.includes(row.id));
      expect({
        words: rows.map(row => row.place),
        misspelled: rows.filter(row => words.filter(word => row.line.includes(word)).join(" | ") !== row.place || words.some(word => row.narrowed.includes(word))).map(row => row.id),
      }).toStrictEqual({ words, misspelled: [] });
    });
    it("the line's start, as wb-tz2.20's refusal #4 F2 finding quotes the case's start form, then each place after and before the phrase the carrier's cut #1 delivery note names, are, in order, the places of the out-of-place rows, the witness aside; each row's narrowed line holds the phrase at its place and its line does not", () => {
      const [, outside = ""] = cureClasses(followUpFinding());
      const places = predicatePlaces();
      const witnesses = NARROWING_MEMBERS.map(member => member.witness);
      const rows = NARROWING_CONTROLS.filter(row => row.item === outside && !witnesses.includes(row.id));
      expect({
        places: rows.map(row => row.place),
        misplaced: rows.filter(row => !placeHeld(row.narrowed, row.place) || placeHeld(row.line, row.place)).map(row => row.id),
      }).toStrictEqual({ places, misplaced: [] });
    });
  });

  describe("MEMBER WITNESSES (wb-o3f8, F1 of wb-zchj's landing 984): narrowsToPinnedPages reads each row's narrowed line, the helper header's own L017, narrowed and its line, a witness the finding names spelled as it words it, unnarrowed - the phrase replaced by a named word, a named word mid-line, after 'for' and before the phrase, and 'on its pinned pages and' with another follower", () => {
    it.each(MEMBER_WITNESSES.map(row => [row.id, row] as const))("%s", (_id, row) => {
      expect({ narrowed: narrowsToPinnedPages(row.narrowed), line: narrowsToPinnedPages(row.line) }).toStrictEqual({ narrowed: true, line: false });
    });
  });

  describe("FOLLOW-UP 2 ANCHOR (wb-o3f8, outside this census): the follow-up bead's F1 finding in the tracker export", () => {
    it("every wb-o3f8 requirement line this census answers occurs verbatim in its notes, and the requirement lines are exactly the F1 finding's members sentence and its optional cheap cure sentence, in both directions", () => {
      const notes = exportRecord(FOLLOW_UP_2).notes;
      const finding = ridesFinding(FOLLOW_UP_2);
      const members = finding.indexOf("nine gate-authored members ");
      const membersEnd = members < 0 ? -1 : finding.indexOf(". Each one is realized", members);
      const cure = finding.indexOf("Optional cheap cure (R694 follow-up): ");
      const cureEnd = cure < 0 ? -1 : finding.indexOf(". Or take ", cure);
      expect({
        missing: FOLLOW_UP_2_REQUIREMENTS.filter(requirement => !notes.includes(requirement.text)).map(requirement => requirement.key),
        lines: FOLLOW_UP_2_REQUIREMENTS.map(requirement => requirement.text),
      }).toStrictEqual({
        missing: [],
        lines: [...(membersEnd < 0 ? [] : [finding.slice(members, membersEnd + 1)]), ...(cureEnd < 0 ? [] : [finding.slice(cure, cureEnd + 1)])],
      });
    });
    it("the members the F1 finding names, each with its parenthetical as the finding words it and in order, are exactly the PREDICATE_MEMBERS rows", () => {
      expect(findingMembers(ridesFinding(FOLLOW_UP_2))).toStrictEqual(PREDICATE_MEMBERS);
    });
    it("the witnesses the F1 finding names, each with the finding's words for its spelling and in order, are exactly the MEMBER_WITNESSES rows; the helper header line it names and quotes is the helper's own line and every row's narrowed line; and each row's line is that line with the spelling the finding gives it, spelling one widening word the export names for the predicate, the row's, and its narrowed line none", () => {
      const finding = ridesFinding(FOLLOW_UP_2);
      const quoted = /The witness edits the helper header line (L\d{3}) \('(.*?)'\) and its CLAIM_LINES mirror/.exec(finding);
      const own = helperClaimLines().find(entry => entry.id === quoted?.[1])?.line ?? "no such helper line";
      const words = predicateWideningWords();
      expect({
        witnesses: MEMBER_WITNESSES.map(row => ({ id: row.id, spelling: row.spelling })),
        quoted: quoted?.[2] ?? "no quoted line",
        elsewhere: MEMBER_WITNESSES.filter(row => row.narrowed !== own).map(row => row.id),
        misspelled: MEMBER_WITNESSES.filter(row => !spelledAsFound(row) || words.filter(word => row.line.includes(word)).join(" | ") !== row.word || words.some(word => row.narrowed.includes(word))).map(row => row.id),
      }).toStrictEqual({ witnesses: findingWitnesses(finding), quoted: own, elsewhere: [], misspelled: [] });
    });
    it("the control classes the F1 finding's cheap cure names - the phrase replaced by a named word; a named word mid-line, before the phrase and after 'for'; 'on its pinned pages and' with another follower - are, in order, the items of the MEMBER_WITNESSES rows, each row's item the class its spelling falls in: the phrase's, a quoted replacement of the phrase by text without it; the follower's, its word the one that class quotes; else the place class", () => {
      const classes = cheapCureClasses(ridesFinding(FOLLOW_UP_2));
      const [phrased = "", placed = "", followed = ""] = classes;
      const follower = /^'(.+?)' with another follower$/.exec(followed)?.[1];
      const classOf = (row: MemberWitness): string => {
        const [, from = "", to = ""] = /^'(.+?)' -> '(.+?)'/.exec(row.spelling) ?? [];
        if (from.includes("on its pinned pages") && to !== "" && !to.includes("on its pinned pages")) return phrased;
        return row.word === follower ? followed : placed;
      };
      expect({ classes: [...new Set(MEMBER_WITNESSES.map(row => row.item))], misclassed: MEMBER_WITNESSES.filter(row => row.item !== classOf(row)).map(row => row.id) }).toStrictEqual({ classes, misclassed: [] });
    });
  });

  describe("NARROWED WORDS (wb-v3a9, F1 of wb-o3f8's landing 997; outside this census): wb-v3a9's own cure and the second cure alternative of wb-o3f8's F1 finding it names, in the tracker export, and this header narrowed to them", () => {
    it("every wb-v3a9 requirement line this census answers occurs verbatim in its own notes, and the requirement lines are exactly its F1 finding's cure sentence and the scope sentence beside it, in both directions; and the words its cure narrows, and the words it narrows them to, are those wb-o3f8's second cure alternative quotes", () => {
      const notes = exportRecord(FOLLOW_UP_3).notes;
      const finding = ridesFinding(FOLLOW_UP_3);
      const cure = finding.indexOf("Cure for the carry: ");
      const scope = finding.indexOf(" A further row-per-spelling cure, ");
      const quoted = /parenthetical \('(.+?)', base :348\) to '(.+?)'\. A further row-per-spelling cure, /.exec(finding);
      const { replaced, narrowing } = narrowingCure();
      expect({
        missing: FOLLOW_UP_3_REQUIREMENTS.filter(requirement => !notes.includes(requirement.text)).map(requirement => requirement.key),
        lines: FOLLOW_UP_3_REQUIREMENTS.map(requirement => requirement.text),
        words: [quoted?.[1] ?? "no quoted words", quoted?.[2] ?? "no quoted words"],
      }).toStrictEqual({
        missing: [],
        lines: [...(cure < 0 || scope < cure ? [] : [finding.slice(cure, scope)]), ...(scope < 0 ? [] : [finding.slice(scope + 1)])],
        words: [replaced, narrowing],
      });
    });
    it("the second cure alternative and the lineage note of wb-o3f8's F1 finding, the sentences wb-v3a9's cure names, occur verbatim in wb-o3f8's notes, and the NARROWING_REQUIREMENTS rows are exactly those two sentences of that finding, in both directions", () => {
      const notes = exportRecord(FOLLOW_UP_2).notes;
      const finding = ridesFinding(FOLLOW_UP_2);
      const alternative = finding.indexOf("Or take F1's second cure alternative ");
      const lineage = finding.indexOf(" Lineage noted as data: ");
      expect({
        missing: NARROWING_REQUIREMENTS.filter(requirement => !notes.includes(requirement.text)).map(requirement => requirement.key),
        lines: NARROWING_REQUIREMENTS.map(requirement => requirement.text),
      }).toStrictEqual({
        missing: [],
        lines: [...(alternative < 0 || lineage < alternative ? [] : [finding.slice(alternative, lineage)]), ...(lineage < 0 ? [] : [finding.slice(lineage + 1)])],
      });
    });
    it("the parenthetical words that alternative quotes stand nowhere in this header as censusHeader reads it, in any letter case, and the words it narrows them to stand in their place, in the NOT CLAIMED sentence on the widening words of the FAIL-CLOSED cases, that place spelled as this header's NARROWED WORDS ROWS entry spells it (cut #2, refusal #1 U1; cut #3, refusal #2 U1)", () => {
      const { replaced, narrowing } = narrowingCure();
      const header = censusHeader();
      const { headings, openings, paragraph } = notClaimedParagraph(NARROWED_PARAGRAPH);
      expect({
        words: [replaced, narrowing],
        replaced: header.toLowerCase().includes(replaced.toLowerCase()) || header.toUpperCase().includes(replaced.toUpperCase()),
        headings,
        openings,
        placed: clausesOf(paragraph).flatMap((clause, at) => (clause.includes(NARROWED_FRAME) ? [{ at, clause }] : [])),
        frames: header.split(NARROWED_FRAME).length - 1,
      }).toStrictEqual({
        words: ["they read the phrase's place and those words", "the cases apply narrowsToPinnedPages to the header's lines"],
        replaced: false,
        headings: 1,
        openings: 1,
        placed: [{ at: 2, clause: `and ${NARROWED_FRAME}${narrowing}, not the line's meaning)` }],
        frames: 1,
      });
    });
    it("the only ROWS entry of this header opening 'NARROWED WORDS (' reads, after 'and the parenthetical words the alternative quotes ', PLACE_WORDS and then its closing sentence on them, and nothing else, as rowsEntries reads it: the words cut #3 spells the replaced words' absence and the sentence's place with (cut #3, refusal #2 U1)", () => {
      const lead = "and the parenthetical words the alternative quotes ";
      const entries = rowsEntries().filter(entry => entry.startsWith("NARROWED WORDS ("));
      expect({ entries: entries.length, tails: entries.map(entry => (entry.includes(lead) ? entry.slice(entry.indexOf(lead) + lead.length) : "no such words")) }).toStrictEqual({
        entries: 1,
        tails: [`${PLACE_WORDS}; and this entry's words from 'stand nowhere' on are exactly those the fourth case holds it to, as rowsEntries reads it (cut #3).`],
      });
    });
  });

  describe("CASE WORDS (wb-v3a9): each FAIL-CLOSED case's title, ROWS entry and body, narrowed to the cases applying narrowsToPinnedPages to the header's lines", () => {
    it("the FAIL-CLOSED cases vitest registers for this file, this header's FAIL-CLOSED ROWS entries and the FAIL_CLOSED_CASES rows are, by head and in order, the same five; and each case's title and ROWS entry hold, after 'wb-v3a9: ', the words that alternative narrows to, and 'narrowsToPinnedPages reads narrowed every ', and none of its row's replaced words", ({ task }) => {
      const registered: string[] = [];
      const walk = (tasks: typeof task.file.tasks): void => {
        for (const child of tasks) {
          if (child.type === "test" && child.name.startsWith("FAIL-CLOSED ")) registered.push(child.name);
          else if (child.type === "suite") walk(child.tasks);
        }
      };
      walk(task.file.tasks);
      const entries = rowsEntries().filter(entry => entry.startsWith("FAIL-CLOSED "));
      const { narrowing } = narrowingCure();
      const headOf = (text: string): string => text.slice(0, text.indexOf(" (") + 2);
      const narrowed = (text: string, row: FailClosedCase): boolean =>
        narrowing !== "" && text.includes(`wb-v3a9: ${narrowing})`) && text.includes("narrowsToPinnedPages reads narrowed every ") && !row.replaced.some(words => text.includes(words));
      expect({
        registered: registered.map(headOf),
        entries: entries.map(headOf),
        unnarrowed: FAIL_CLOSED_CASES.filter((row, at) => !narrowed(registered[at] ?? "", row) || !narrowed(entries[at] ?? "", row)).map(row => row.id),
      }).toStrictEqual({ registered: FAIL_CLOSED_CASES.map(row => row.head), entries: FAIL_CLOSED_CASES.map(row => row.head), unnarrowed: [] });
    });
    it("each FAIL-CLOSED case's body, as this file spells it, binds lines to helperClaimLines() first and hands narrowsToPinnedPages, negated as the whole body of the filter of its unnarrowed list, its row's argument over its row's list, a const of the body read from those lines - the argument reading lines itself, or the list building no entry of its own; it declares none of the names that application reads, and it expects that list empty", () => {
      expect(failClosedApplications()).toStrictEqual(
        FAIL_CLOSED_CASES.map(row => ({ head: row.head, bindsLines: true, receiver: row.receiver, receiverReadsLines: true, argument: row.argument, readsHeaderLines: true, expectsEmpty: true, shadowed: [] })),
      );
    });
  });

